    def open_structure(self, *, alphafold=None, assembly=None, chain=None, pdb=None):
        """Open a structure.

        Opens a structure in the Structure view: a PDB entry by its ID, or the AlphaFold DB model of
        a UniProt accession ("target": the target's), fetched through the program (cached, then
        available offline). A file of your own opens with open_files. Returns the structure in
        words: its chains, the residues observed, its assemblies and what else it holds.

        Args:
            alphafold: A UniProt accession, such as P62993, for its AlphaFold DB model; "target" for
                the target's. Optional; a string.
            assembly: A biological assembly by its id ("1"), or "asym" for the asymmetric unit; the
                coordinates as deposited if not given. Optional; a string.
            chain: The chain to map the workspace's target on; the chain that holds the most of it
                if not given. Optional; a string.
            pdb: A PDB ID, such as 2VWF. Optional; a string.

        Returns:
            A Result: the message and the data MaveScape answered with.
        """
        return self.call("open_structure", **{"alphafold": alphafold, "assembly": assembly, "chain": chain, "pdb": pdb})

    def find_structures(self):
        """Find structures of the target.

        The PDB entries that cover the workspace's target (its UniProt accession), from PDBe's SIFTS
        through the program: ranked by the target positions each covers, then resolution, each with
        its method, chains and positions; and that its AlphaFold DB model covers it all.

        Returns:
            A Result: the message and the data MaveScape answered with.
        """
        return self.call("find_structures")

    def map_structure(self, *, chain=None):
        """Map the target onto the structure.

        Maps the workspace's target onto the structure shown: the target aligned to each chain
        (BLOSUM62, free end gaps), and on the chain chosen each position on a residue (identical or
        another), in the structure's sequence but not observed, missing from it, or outside it;
        ambiguous positions; the entry's own record of the UniProt residues compared. Returns the
        mapping in words and by position.

        Args:
            chain: The chain to map the target on; the one that holds the most of it if not given.
                Optional; a string.

        Returns:
            A Result: the message and the data MaveScape answered with.
        """
        return self.call("map_structure", **{"chain": chain})

    def set_structure(self, *, add=None, assembly=None, calibration=None, color=None, fit=None, focus=None, label=None, pick=None, select=None, show=None, side=None, style=None, substitution=None, surface=None, threshold=None):
        """Draw, color and select on the structure.

        Draws the structure shown another way (style, color, surface, assembly), colors its residues
        by their target positions' scores (the run and condition the map shows, in the map's colors:
        filtered and missing positions gray, never the wild type's color), and selects residues in
        Proteoscope's selection language, draws them in a style of their own, labels them and
        focuses on their neighborhood; or picks a residue as a click does (its substitutions
        selected on the map, its position in the inspector). Returns the structure's state: what is
        selected, labeled and focused on, the scores colored by, and the renderer (WebGPU, or the
        Canvas renderer, which draws no surfaces).

        Args:
            add: pick: add the residue to the selection (or take it away), as a ⌘-click does.
                Optional; TRUE or FALSE (Python: True or False).
            assembly: A biological assembly by its id ("1"), or "asym" for the asymmetric unit;
                clears the selection. Optional; a string.
            calibration: color fraction: a published calibration of the record whose scores the run
                is, by title or number (from 1), instead of a threshold. Optional; a string.
            color: By the scores: median, mean, minimum, maximum, fraction (abnormal-like, with
                threshold or calibration), count (substitutions scored), substitution (with
                substitution), uncertainty (median SE), disagreement (the comparison Compare shows) or
                qc. Or the structure's own: class (each position's structural class: buried, exposed,
                interface, disordered), chain, entity, rainbow, secondary, moltype, element, residue,
                hydrophobicity, nucleotide, bfactor, plddt (a predicted model) or uniform. Optional; a
                string.
            fit: Fit the whole structure in the view. Optional; TRUE or FALSE (Python: True or
                False).
            focus: Focus on the selected residues and their neighbors within 5 Å, side chains drawn
                (false: the whole structure again). Optional; TRUE or FALSE (Python: True or False).
            label: Label the selected residues (false: remove their labels). Optional; TRUE or FALSE
                (Python: True or False).
            pick: A residue picked as a click picks it: "A 183" (chain and number, with an insertion
                code if any); its position's substitutions selected on the map, the position in the
                inspector. Optional; a string.
            select: Residues to select: "resn CYS", "chain A and resi 40-80", "within 5 of ligand",
                "helix and chain B", "pos 30-40" (target positions, on the chain mapped), "uniprot
                188-198" (the reference's); empty to clear the selection. Optional; a string.
            show: How the selected residues are drawn: sticks, ball-stick, spacefill, hide or none
                (as the rest). Optional; a string.
            side: color fraction: below or above the threshold is abnormal-like (the readout's loss
                side if not given). Optional; a string.
            style: cartoon, ball-stick, sticks, spacefill or trace. Optional; a string.
            substitution: color substitution: the amino acid each residue's substitution to is shown
                (A or Ala; * or Ter for a stop). Optional; a string.
            surface: off, ses (molecular), sas (solvent-accessible), vdw or gaussian; WebGPU only.
                Optional; a string.
            threshold: color fraction: the score beyond which a substitution is abnormal-like
                (research use). Optional; a number.

        Returns:
            A Result: the message and the data MaveScape answered with.
        """
        return self.call("set_structure", **{"add": add, "assembly": assembly, "calibration": calibration, "color": color, "fit": fit, "focus": focus, "label": label, "pick": pick, "select": select, "show": show, "side": side, "style": style, "substitution": substitution, "surface": surface, "threshold": threshold})

    def render_structure(self, *, legend=None, light=None, scale=None, file=None):
        """The Structure view as a picture.

        The Structure view as a picture (a PNG), as a figure panel of it is drawn: the structure as
        shown, its coloring's legend below (legend: false, the view alone), with what it shows in
        words.

        Args:
            legend: Draw the legend below the view (true if not given). Optional; TRUE or FALSE
                (Python: True or False).
            light: On white, whatever the window's theme. Optional; TRUE or FALSE (Python: True or
                False).
            scale: The picture's size against the view's, from 0.5 to 4 (2 if not given). Optional;
                a number.
            file: Optional; save the picture to this path as a PNG file (and ask for it).

        Returns:
            A Result: the message and the data MaveScape answered with.
        """
        result = self.call("render_structure", **{"legend": legend, "light": light, "scale": scale})
        if file is not None:
            result.save_image(file)
        return result

    def structure_evidence(self, *, fraction=None, partner=None, seed=None):
        """The structure as evidence.

        What the structure shown says of the target's positions: each one's structural class
        (buried, exposed, interface with the partners chosen, or a predicted model's disordered
        region), from DSSP's secondary structure, the solvent accessibility (DSSP's radii),
        StructureMap's exposure and the partners within 4 Å; the median scores of each class against
        the rest (Mann–Whitney, BH-adjusted); and whether the least tolerant positions lie closer
        together than positions of the same burial (pairs within 8 Å against seeded draws within
        strata of relative accessibility). The same are tracks beside the map (list_tracks).

        Args:
            fraction: The share of positions called least tolerant for the cluster test (0.2 if not
                given). Optional; a number.
            partner: The partner the interface is read with: "all" (every other chain, ligand and
                ion but common additives, the default), or one by its id or label ("chain:B",
                "ligand:A:1352:TLA"). Optional; a string.
            seed: The seed of the cluster test's draws (1 if not given). Optional; a whole number.

        Returns:
            A Result: the message and the data MaveScape answered with.
        """
        return self.call("structure_evidence", **{"fraction": fraction, "partner": partner, "seed": seed})

